{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Ethosuximide, a small lipophilic molecule with minimal polar surface area, has an absolute oral bioavailability of 90–95% in humans, supporting that small, non-acidic, non-phenolic molecules can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Cilomilast is completely bioavailable (96%, range 92–102%) after oral administration in humans, demonstrating that even molecules with polar groups can achieve high oral bioavailability when permeability is favorable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nevirapine, a lipophilic amine, has an absolute oral bioavailability of 91 ± 8% in healthy volunteers, supporting high F for lipophilic amine-containing drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pentazocine has a low oral bioavailability of 18%, but this is attributed to its phenolic group undergoing first-pass glucuronidation; the query lacks a phenol, so this contradictory evidence has low transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Rasagiline, a small lipophilic secondary amine, has an absolute oral bioavailability of 36%, which is above the 20% threshold but lower than expected; its extensive first-pass metabolism is due to the propargylamine moiety, which is absent in the query's sterically hindered primary amine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is memantine, a small lipophilic primary amine with an adamantane cage and no metabolic liability groups (no phenol, no carboxylic acid, no propargylamine). High-F analogues such as ethosuximide, cilomilast, and nevirapine support high oral bioavailability, while the only clearly low-F analogue (pentazocine) owes its low F to a phenolic group absent in the query. Rasagiline's F of 36% is still above the 20% threshold and its low value is linked to a propargylamine moiety not present in the query. Therefore, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for memantine or a close adamantane analogue is present in the evidence set.",
    "The query's primary amine is mostly ionized at physiological pH, but its permeability and transporter interactions are not directly evidenced."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C09"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "small lipophilic high-F molecules"
    },
    {
      "applicability": "low",
      "card_ids": ["C25"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "phenolic low-F molecules"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C12"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "small lipophilic amine low-F molecules"
    }
  ],
  "revision_action": "initial"
}

